"use client";

import { FlowDiagram } from "@diax/react";
import {
  ArtifactNode,
  DecisionNode,
  DiagramFrame,
  StageNode,
} from "@diax/ui-react/presentation";
import type { DiaxNode, DiaxRelation } from "diax";
import type { KeyboardEvent, ReactNode } from "react";

const nodeClass =
  "w-[190px] max-w-[190px] [--diax-node-radius:2px] [&_[data-diax-ui-part=eyebrow]]:text-[12px] [&_[data-diax-ui-part=meta-label]]:text-[12px] [&_[data-diax-ui-part=badge]]:text-[12px] [&_[data-diax-ui-part=footer]]:text-[12px] [&_[data-diax-ui-part=artifact-manifest]_dt]:text-[12px] [&_[data-diax-ui-part=artifact-manifest]_dd]:text-[12px]";

const nodes = [
  {
    id: "draft",
    content: (
      <StageNode
        className={nodeClass}
        step="State 01"
        title="Candidate draft"
        status="active"
        statusLabel="mutable"
        owner="Release owner"
        description="Version, changelog and provenance are assembled as one candidate."
      />
    ),
  },
  {
    id: "qualified",
    content: (
      <DecisionNode
        className={nodeClass}
        title="Qualification review"
        status="proposed"
        statusLabel="evidence gate"
        outcome="Advance or reject"
        criteria={["Packed consumer passes", "Three-browser receipt", "Known risk recorded"]}
        owner="Maintainer review"
      />
    ),
  },
  {
    id: "released",
    content: (
      <ArtifactNode
        className={nodeClass}
        name="Published alpha"
        kind="Immutable artifact"
        version="0.1.0-next.0"
        source="Qualified candidate"
        status="published"
        statusLabel="available"
        description="Consumers resolve the same packed files that passed qualification."
      />
    ),
  },
  {
    id: "rejected",
    content: (
      <DecisionNode
        className={nodeClass}
        title="Candidate rejected"
        status="rejected"
        statusLabel="repair required"
        outcome="Return to draft"
        rationale="A failed gate keeps its complete evidence instead of publishing a partial artifact."
        owner="Release owner"
      />
    ),
  },
  {
    id: "retired",
    content: (
      <StageNode
        className={nodeClass}
        step="Terminal"
        title="Artifact retired"
        status="complete"
        statusLabel="superseded"
        owner="Registry policy"
        description="A replacement or expiry closes the release lifecycle."
      />
    ),
  },
] satisfies readonly DiaxNode<ReactNode>[];

const relations = [
  transition("draft-qualified", "draft", "qualified", "submit evidence"),
  transition("qualified-released", "qualified", "released", "all gates pass", "#315d88"),
  transition("qualified-rejected", "qualified", "rejected", "gate fails", "#a94f43"),
  transition("rejected-draft", "rejected", "draft", "repair candidate", "#a96320", true),
  transition("released-qualified", "released", "qualified", "rollback incident", "#a94f43", true),
  transition("released-retired", "released", "retired", "superseded", "#47715d"),
] satisfies readonly DiaxRelation<ReactNode>[];

export default function ReleaseLifecycle() {
  return (
    <DiagramFrame
      data-showcase-corpus="release-lifecycle"
      eyebrow="Release lifecycle · Automatic topology"
      title="A release is a state machine, not a timeline"
      description="Qualification owns advancement. Rejection and rollback remain first-class transitions instead of footnotes."
      caption="DiaX plans the state ranks, measured labels and feedback gutters; no transition contains a bend point or channel coordinate."
      className="w-full max-w-[1120px] [--diax-accent:#315d88] [--diax-frame-bg:#f1f4f5] [--diax-frame-radius:2px] [--diax-frame-shadow:none] [--diax-node-bg:#fbfcfc] [--diax-node-border:#aebbc0] [--diax-node-shadow:none] [--diax-node-text:#172126] [--diax-ui-radius:2px]"
    >
      <LifecycleLegend />

      <section
        aria-label="Scrollable release candidate lifecycle"
        className="mt-4 overflow-x-auto border border-[#bac5c9] bg-[#f8fafb] p-4 outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#315d88]"
        // biome-ignore lint/a11y/noNoninteractiveTabindex: keyboard users need a focus stop for the intentionally wide lifecycle map.
        tabIndex={0}
        onKeyDown={scrollOnArrow}
      >
        <FlowDiagram
          nodes={nodes}
          relations={relations}
          direction="horizontal"
          density="spacious"
          centered
          highlightOnHover
          className="min-w-[980px]"
          renderEdgeLabel={(label) => <TransitionLabel>{label}</TransitionLabel>}
        />
      </section>
    </DiagramFrame>
  );
}

function transition(
  id: string,
  from: string,
  to: string,
  label: string,
  color = "#596b73",
  dashed = false,
): DiaxRelation<ReactNode> {
  return {
    id,
    from,
    to,
    label,
    color,
    style: dashed ? "dashed" : "solid",
    targetMarker: "arrow",
    gap: 7,
  };
}

function TransitionLabel({ children }: { children: ReactNode }) {
  return (
    <span className="border border-[#aebbc0] bg-[#fbfcfc] px-1.5 py-0.5 font-mono text-[11px] font-semibold text-[#40525a]">
      {children}
    </span>
  );
}

function LifecycleLegend() {
  return (
    <ul
      aria-label="Lifecycle relation legend"
      className="m-0 grid list-none border-y border-[#bac5c9] p-0 text-[11px] text-[#526169] sm:grid-cols-3"
    >
      <LegendItem label="Advance with evidence" color="#315d88" />
      <LegendItem label="Reject or rollback" color="#a94f43" dashed />
      <LegendItem label="Terminal transition" color="#47715d" />
    </ul>
  );
}

function LegendItem({ label, color, dashed = false }: { label: string; color: string; dashed?: boolean }) {
  return (
    <li className="flex items-center gap-2 px-3 py-2 sm:border-l sm:first:border-l-0">
      <span
        aria-hidden="true"
        className={`w-8 border-t-2 ${dashed ? "border-dashed" : ""}`}
        style={{ borderColor: color }}
      />
      {label}
    </li>
  );
}

function scrollOnArrow(event: KeyboardEvent<HTMLElement>) {
  if (event.target !== event.currentTarget) return;
  const direction = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0;
  if (direction === 0) return;
  event.preventDefault();
  event.currentTarget.scrollBy({ left: direction * Math.max(120, event.currentTarget.clientWidth * 0.7) });
}
